  "background": "本篇作者为白居易，作品收入《白氏长庆集》。诗歌通过具体景物、人物或生活场景展开，体现唐代诗歌重视意境、情感与语言锤炼的特点。本条为节选，正文以省略号标示删节处，便于先读核心段落。",
