{
  "id": 231,
  "type": "宋词",
  "title": "浣溪沙·漠漠轻寒上小楼",
  "author": "秦观",
  "source": "《淮海居士长短句》",
  "category": "月色清寂",
  "text": "漠漠轻寒上小楼，晓阴无赖似穷秋。\n淡烟流水画屏幽。\n自在飞花轻似梦，无边丝雨细如愁。\n宝帘闲挂小银钩。",
  "translations": [
    [
      "全文译意",
      "淡淡寒意笼罩小楼，清晨阴云如深秋。飞花轻柔如梦，细雨绵绵如愁，营造幽微朦胧的春日情境。"
    ]
  ],
  "background": "秦观的这篇作品收入《淮海居士长短句》。作品通过具体景物、人物经历或历史典故展开表达，体现了中国古典文学丰富的题材与审美传统。",
  "appreciation": "作品以凝练的语言组织意象，情景交融，表达了月色清寂相关的情感或思考。阅读时可留意关键词句、结构变化以及作者寄托其中的情怀。"
}
,
{
  "id": 232,
  "type": "宋词",
  "title": "定风波·南海归赠王定国侍人寓娘",
  "author": "苏轼",
  "source": "《东坡乐府》",
  "category": "人生哲理",
  "text": "常羡人间琢玉郎，天应乞与点酥娘。\n尽道清歌传皓齿，风起，雪飞炎海变清凉。\n万里归来颜愈少，微笑，笑时犹带岭梅香。\n试问岭南应不好，却道：此心安处是吾乡。",
  "translations": [
    [
      "全文译意",
      "词中赞美柔奴历经岭南艰苦仍从容乐观。面对岭南是否艰苦的询问，她回答心安之处便是故乡。"
    ]
  ],
  "background": "苏轼的这篇作品收入《东坡乐府》。作品通过具体景物、人物经历或历史典故展开表达，体现了中国古典文学丰富的题材与审美传统。",
  "appreciation": "作品以凝练的语言组织意象，情景交融，表达了人生哲理相关的情感或思考。阅读时可留意关键词句、结构变化以及作者寄托其中的情怀。"
}
