{
  "id": 242,
  "type": "宋词",
  "title": "定风波·自春来",
  "author": "柳永",
  "source": "《乐章集》",
  "category": "爱情情感",
  "text": "自春来、惨绿愁红，芳心是事可可。\n日上花梢，莺穿柳带，犹压香衾卧。\n暖酥消，腻云亸，终日厌厌倦梳裹。\n无那。恨薄情一去，音书无个。\n早知恁么，悔当初、不把雕鞍锁。\n向鸡窗，只与蛮笺象管，拘束教吟课。\n镇相随，莫抛躲。针线闲拈伴伊坐。\n和我。免使年少，光阴虚过。",
  "translations": [
    [
      "全文译意",
      "词中女子因爱人远行音信全无而懊悔，想象若能留住对方，便可相伴度日，写出深切的相思。"
    ]
  ],
  "background": "柳永的这篇作品收入《乐章集》。作品通过具体景物、人物经历或历史典故展开表达，体现了中国古典文学丰富的题材与审美传统。",
  "appreciation": "作品以凝练的语言组织意象，情景交融，表达了爱情情感相关的情感或思考。阅读时可留意关键词句、结构变化以及作者寄托其中的情怀。"
}
