{
  "id": 253,
  "type": "先秦诗歌",
  "title": "硕鼠",
  "author": "《诗经·魏风》",
  "source": "《诗经》",
  "category": "人生哲理",
  "text": "硕鼠硕鼠，无食我黍！\n三岁贯女，莫我肯顾。\n逝将去女，适彼乐土。\n乐土乐土，爰得我所。",
  "translations": [
    [
      "全文译意",
      "诗人把剥削者比作贪食的大老鼠，控诉其贪婪无厌，并表达离开压迫、寻找安居之地的愿望。"
    ]
  ],
  "background": "《诗经·魏风》的这篇作品收入《诗经》。作品通过具体景物、人物经历或历史典故展开表达，体现了中国古典文学丰富的题材与审美传统。",
  "appreciation": "作品以凝练的语言组织意象，情景交融，表达了人生哲理相关的情感或思考。阅读时可留意关键词句、结构变化以及作者寄托其中的情怀。"
}
