{
  "id": 306,
  "type": "唐诗",
  "title": "望月怀远",
  "author": "张九龄",
  "source": "《全唐诗》",
  "category": "离别思念",
  "text": "海上生明月，\n天涯共此时。\n情人怨遥夜，\n竟夕起相思。",
  "translations": [
    ["海上生明月", "茫茫大海上升起一轮皎洁明月。"],
    ["天涯共此时", "远隔天涯的人们共享这同一轮月色。"],
    ["情人怨遥夜", "多情的人怨恨这漫漫长夜。"],
    ["竟夕起相思", "整夜心中涌起无尽的思念。"]
  ],
  "background": "张九龄是盛唐名相，这首望月怀远是月夜怀人千古名篇。望月触发对远方亲人的思念，意境阔大而情思细腻。",
  "appreciation": "开篇“海上生明月，天涯共此时”境界雄浑开阔，由宏大海景转入个人相思。明月作为共同的意象，把相隔遥远的人联系在一起，情景交融，含蓄深沉。"
},
{
  "id": 307,
  "type": "唐诗",
  "title": "望月有感",
  "author": "白居易",
  "source": "《白氏长庆集》",
  "category": "亲情记忆",
  "text": "时难年荒世业空，弟兄羁旅各西东。\n田园寥落干戈后，骨肉流离道路中。\n吊影分为千里雁，辞根散作九秋蓬。\n共看明月应垂泪，一夜乡心五处同。",
  "translations": [
    [
      "全文译意",
      "时世艰难年岁饥荒，家业荡然，兄弟漂泊各奔东西。战乱之后田园荒芜，亲人离散流落四方。孤影如同千里离群大雁，又像离根的秋蓬。共望明月应当落泪，一夜之间五地之人怀着同样思乡之心。"
    ]
  ],
  "background": "本诗作于战乱时期，白居易兄弟姐妹离散各地。诗人借明月抒发骨肉分离的痛苦与共同的乡愁。",
  "appreciation": "以雁、蓬比喻亲人离散漂泊，形象贴切。结尾写分隔五地的亲人共对明月，将个人苦难上升到骨肉同胞共同的情感，感染力极强。"
},
{
  "id": 308,
  "type": "唐诗",
  "title": "金缕衣",
  "author": "杜秋娘",
  "source": "《全唐诗》",
  "category": "人生哲理",
  "text": "劝君莫惜金缕衣，\n劝君惜取少年时。\n花开堪折直须折，\n莫待无花空折枝。",
  "translations": [
    ["劝君莫惜金缕衣", "劝你不要太过爱惜华贵的金缕衣裳。"],
    ["劝君惜取少年时", "劝你好好珍惜青春年少的美好时光。"],
    ["花开堪折直须折", "花儿盛开可以采摘的时候就应当及时采摘。"],
    ["莫待无花空折枝", "不要等到花儿凋零，只能徒然折下空树枝。"]
  ],
  "background": "相传为杜秋娘所作，以劝告的口吻劝勉世人珍惜青春年华，莫要贪恋物质而虚度光阴。",
  "appreciation": "全诗用比喻说理，语言浅白直白。以金缕衣与少年时对比，又以花的盛衰比喻时光流逝，劝人把握当下，意蕴耐人回味。"
},
{
  "id": 309,
  "type": "宋词",
  "title": "苏幕遮·怀旧",
  "author": "范仲淹",
  "source": "《范文正公集》",
  "category": "羁旅乡愁",
  "text": "碧云天，黄叶地，秋色连波，波上寒烟翠。\n山映斜阳天接水，芳草无情，更在斜阳外。\n黯乡魂，追旅思，夜夜除非，好梦留人睡。\n明月楼高休独倚，酒入愁肠，化作相思泪。",
  "translations": [
    [
      "全文译意",
      "碧云满天，黄叶铺地，秋意连着水波，水面笼罩翠绿寒烟。夕阳映山，水天相接，芳草漫延到夕阳之外。羁旅乡愁黯然萦绕，只有好梦才能得以安睡。不要独自高楼望月，酒流入愁肠，都化作思念的泪水。"
    ]
  ],
  "background": "范仲淹离开家乡在外宦游，秋日触景生情写下这首羁旅怀人词作。上片写景，下片直抒思乡的愁苦。",
  "appreciation": "上阕铺展阔大苍凉的秋日图景，芳草斜阳暗含乡关遥远。下阕写深夜怀乡，借酒消愁却愁绪更浓。景与情高度融合，苍凉而深情。"
},
{
  "id": 310,
  "type": "古文",
  "title": "记承天寺夜游",
  "author": "苏轼",
  "source": "《东坡志林》",
  "category": "月色清寂",
  "text": "元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。\n念无与为乐者，遂至承天寺寻张怀民。\n怀民亦未寝，相与步于中庭。\n庭下如积水空明，水中藻、荇交横，盖竹柏影也。\n何夜无月？何处无竹柏？但少闲人如吾两人者耳。",
  "translations": [
    [
      "全文译意",
      "元丰六年十月十二日夜晚，我正准备脱衣睡觉，月光照进门内，便高兴出门散步。想到没有同乐之人，于是到承天寺找张怀民。张怀民也没有睡，我们一同在庭院散步。庭院月光像积水澄澈透明，水草交错原来是竹子柏树的影子。哪一夜没有月亮？哪里没有竹柏？只是缺少像我们两个清闲的人罢了。"
    ]
  ],
  "background": "苏轼被贬黄州，仕途失意。一个月夜，他与同样贬谪的张怀民夜游承天寺，写下这篇八十余字小品文。",
  "appreciation": "文章短小精悍，以积水比喻月色，意境空灵。结尾“闲人”二字意蕴丰富，包含贬谪的苦闷、赏月的悠然，是逆境中自我宽慰的人生境界。"
},
{
  "id": 311,
  "type": "元曲",
  "title": "水仙子·咏江南",
  "author": "张养浩",
  "source": "《全元散曲》",
  "category": "山水自然",
  "text": "一江烟水照晴岚，两岸人家接画檐，\n芰荷丛一段秋光淡。\n看沙鸥舞再三，卷香风十里珠帘。\n画船儿天边至，酒旗儿风外飐。\n爱杀江南！",
  "translations": [
    [
      "全文译意",
      "一江烟水映着山间雾气，两岸人家屋檐相连。荷塘间秋光清淡。沙鸥频频飞舞，香风卷起十里珠帘。画船从天边驶来，酒旗在风中招展。江南实在令人喜爱！"
    ]
  ],
  "background": "张养浩这首元曲小令描绘江南水乡风光，选取江水、人家、荷花、沙鸥、画船、酒旗诸多意象，赞美江南的富庶秀丽。",
  "appreciation": "画面层层铺排，从山水人家到风物民俗，最后直抒胸臆。语言明快，景物鲜活，读来仿佛置身江南水乡。"
},
{
  "id": 312,
  "type": "先秦诗歌",
  "title": "击鼓（节选）",
  "author": "佚名",
  "source": "《诗经·邶风》",
  "category": "爱情情感",
  "text": "死生契阔，与子成说。\n执子之手，与子偕老。",
  "translations": [
    ["死生契阔", "无论生死离合。"],
    ["与子成说", "我曾经与你立下誓言。"],
    ["执子之手", "紧紧握住你的手。"],
    ["与子偕老", "和你相伴一直到老。"]
  ],
  "background": "出自《诗经·邶风·击鼓》，原诗写戍卒征战思乡，这四句本是战友之间的约定，后世常用来形容爱情的相守誓言。",
  "appreciation": "语言质朴简短，却重若千钧。朴素直白的承诺，跨越千年，成为中国人心中关于相伴相守的经典表达。"
},
{
  "id": 313,
  "type": "唐诗",
  "title": "塞下曲·其三",
  "author": "卢纶",
  "source": "《全唐诗》",
  "category": "家国情怀",
  "text": "月黑雁飞高，\n单于夜遁逃。\n欲将轻骑逐，\n大雪满弓刀。",
  "translations": [
    ["月黑雁飞高", "夜色漆黑，大雁高高飞向夜空。"],
    ["单于夜遁逃", "敌军首领趁着黑夜仓皇逃跑。"],
    ["欲将轻骑逐", "将军正要率领轻骑兵前去追击。"],
    ["大雪满弓刀", "漫天大雪落满将士的弓箭和战刀。"]
  ],
  "background": "卢纶《塞下曲》组诗描写边塞军旅战斗生活。本首写雪夜追击逃敌的场景，不写激烈厮杀，重在烘托将士气概。",
  "appreciation": "全诗没有正面写交战，选取月黑、夜逃、追击、大雪满弓刀几个镜头。以环境烘托人物，风雪苦寒反衬将士勇武，画面感极强，余味无穷。"
},
{
  "id": 314,
  "type": "唐诗",
  "title": "塞下曲·其二",
  "author": "卢纶",
  "source": "《全唐诗》",
  "category": "家国情怀",
  "text": "林暗草惊风，\n将军夜引弓。\n平明寻白羽，\n没在石棱中。",
  "translations": [
    ["林暗草惊风", "昏暗树林中草丛忽然被风吹动。"],
    ["将军夜引弓", "将军在夜色中拉弓射箭。"],
    ["平明寻白羽", "天亮之后寻找那支白色箭羽。"],
    ["没在石棱中", "发现箭头深深嵌进石头棱角里面。"]
  ],
  "background": "取材于汉代李广射石的典故。夜晚误把石头当作猛虎开弓射箭，第二天才发现箭射入石，表现将军过人臂力与勇武。",
  "appreciation": "叙事小诗，情节完整有戏剧性。短短二十字完成环境、动作、结果全过程，塑造出勇武过人的将军形象。"
},
{
  "id": 315,
  "type": "宋词",
  "title": "清平乐·六盘山",
  "author": "毛泽东",
  "source": "《毛泽东诗词》",
  "category": "家国情怀",
  "text": "天高云淡，\n望断南飞雁。\n不到长城非好汉，\n屈指行程二万。\n六盘山上高峰，\n红旗漫卷西风。\n今日长缨在手，\n何时缚住苍龙？",
  "translations": [
    [
      "全文译意",
      "长空高远，云朵清淡，目送南飞大雁直到天际。不能抵达长城就不算英雄，算一算已经行军二万里。六盘山高峰之上，红旗在西风中舒展翻卷。如今我们手握武装，什么时候能够擒获敌人？"
    ]
  ],
  "background": "创作于红军长征翻越六盘山之时。登高望远回顾两万五千里长征，抒发豪迈壮志与革命信念。",
  "appreciation": "上阕写景叙事，下阕转入抒怀。景象开阔，气势雄浑，把现实行军和远大理想结合，充满昂扬的战斗豪情。"
},
{
  "id": 316,
  "type": "古文",
  "title": "鲁山山行",
  "author": "梅尧臣",
  "source": "《宛陵先生集》",
  "category": "山水自然",
  "text": "适与野情惬，千山高复低。\n好峰随处改，幽径独行迷。\n霜落熊升树，林空鹿饮溪。\n人家在何许？云外一声鸡。",
  "translations": [
    [
      "全文译意",
      "山野风光正合我的爱好，群山高高低低连绵起伏。美好的山峰姿态处处变化，独自走幽静小路不觉迷路。霜落之后熊爬上树木，林子空旷，鹿到溪边饮水。人家究竟在哪里？云雾之外传来一声鸡鸣。"
    ]
  ],
  "background": "梅尧臣北宋诗人，这首写鲁山游历，写山野之间所见各种景物，在山行的迷路之中体会山林野趣。",
  "appreciation": "移步换景，山峰随着行走不断变换模样。熊、鹿是山中生灵，结尾鸡鸣从云外传来，以声响暗示人居，余味悠远。"
},
{
  "id": 317,
  "type": "唐诗",
  "title": "渔暮",
  "author": "张志和",
  "source": "《全唐诗》",
  "category": "山水自然",
  "text": "西塞山前白鹭飞，\n桃花流水鳜鱼肥。\n青箬笠，绿蓑衣，\n斜风细雨不须归。",
  "translations": [
    ["西塞山前白鹭飞", "西塞山前白鹭自在飞翔。"],
    ["桃花流水鳜鱼肥", "桃花盛开，春水上涨，鳜鱼肥美。"],
    ["青箬笠，绿蓑衣", "头戴青色斗笠，身披绿色蓑衣。"],
    ["斜风细雨不须归", "微风细雨之中，不必急着回家。"]
  ],
  "background": "即《渔歌子》，是唐代渔父词代表作，描写江南渔父隐逸山水，自得其乐的生活。",
  "appreciation": "色彩清丽，景物鲜活。白鹭、桃花、流水、渔翁构成一幅江南水墨画卷，表达对自在山水生活的向往。"
},
{
  "id": 318,
  "type": "先秦经典",
  "title": "大学（节选）",
  "author": "曾子及其门人",
  "source": "《礼记·大学》",
  "category": "人生哲理",
  "text": "古之欲明明德于天下者，先治其国；\n欲治其国者，先齐其家；\n欲齐其家者，先修其身；\n欲修其身者，先正其心；\n欲正其心者，先诚其意。",
  "translations": [
    [
      "全文译意",
      "古代想要向天下弘扬光明品德的人，先要治理好自己的国家；想要治理国家，先要整顿家庭；想要整顿家庭，先要修养自身品性；想要修养自身，先要端正内心；想要端正内心，先要使自己的意念真诚。"
    ]
  ],
  "background": "出自儒家经典《大学》，提出格物、致知、诚意、正心、修身、齐家、治国、平天下的人生进阶路径。节选修身之前的重要链条。",
  "appreciation": "层层递进，逻辑严密。阐明个人修养是家庭、国家治理的根基，体现儒家向内修身、向外担当的理想。"
}
{
  "id": 319,
  "type": "唐诗",
  "title": "送魏二",
  "author": "王昌龄",
  "source": "《全唐诗》",
  "category": "离别思念",
  "text": "醉别江楼橘柚香，\n江风引雨入舟凉。\n忆君遥在潇湘月，\n愁听清猿梦里长。",
  "translations": [
    ["醉别江楼橘柚香", "在橘柚飘香的江楼上饮酒送别友人。"],
    ["江风引雨入舟凉", "江风携着细雨吹进船舱，带来阵阵凉意。"],
    ["忆君遥在潇湘月", "想象你在潇湘的月色之下漂泊远方。"],
    ["愁听清猿梦里长", "在梦里也要听凄清猿啼，满怀愁绪。"]
  ],
  "background": "这是王昌龄的送别诗，不直接写眼前离别，而是虚拟友人抵达之后的孤寂梦境，虚实结合。",
  "appreciation": "前两句写眼前实景，后两句跳到对方未来的境遇。把离愁寄托在对方的梦里，构思新颖，含蓄悠远。"
},
{
  "id": 320,
  "type": "唐诗",
  "title": "采莲曲·其二",
  "author": "王昌龄",
  "source": "《全唐诗》",
  "category": "四时风物",
  "text": "荷叶罗裙一色裁，\n芙蓉向脸两边开。\n乱入池中看不见，\n闻歌始觉有人来。",
  "translations": [
    ["荷叶罗裙一色裁", "采莲女子的罗裙和荷叶像是同一块布料裁成。"],
    ["芙蓉向脸两边开", "荷花向着少女脸庞两边盛放。"],
    ["乱入池中看不见", "混入荷塘花丛，人花交融，分辨不出人影。"],
    ["闻歌始觉有人来", "听到歌声，才发觉荷塘中有人。"]
  ],
  "background": "王昌龄组诗《采莲曲》中的名篇，刻画江南采莲少女，人花相映。",
  "appreciation": "人与景物浑然一体，视觉消失靠听觉显现人物。画面灵动，充满江南水乡鲜活气息。"
},
{
  "id": 321,
  "type": "唐诗",
  "title": "蜀道后期",
  "author": "张说",
  "source": "《全唐诗》",
  "category": "羁旅乡愁",
  "text": "客心争日月，\n来往预期程。\n秋风不相待，\n先至洛阳城。",
  "translations": [
    ["客心争日月", "游子归心迫切，仿佛要与日月赛跑。"],
    ["来往预期程", "出行归来都预先算好归期。"],
    ["秋风不相待", "可秋风不肯等待我的脚步。"],
    ["先至洛阳城", "抢先一步，已经吹到了洛阳城中。"]
  ],
  "background": "作者出使蜀地，归期延误，借秋风先回故乡抒发羁旅的怅惘。",
  "appreciation": "拟人写秋风，把归乡不得的遗憾写得轻巧。不直接诉苦，借秋风的抢先抵达反衬人滞留在外。"
},
{
  "id": 322,
  "type": "唐诗",
  "title": "渡汉江",
  "author": "宋之问",
  "source": "《全唐诗》",
  "category": "羁旅乡愁",
  "text": "岭外音书断，\n经冬复历春。\n近乡情更怯，\n不敢问来人。",
  "translations": [
    ["岭外音书断", "被贬到岭南，和家乡书信完全断绝。"],
    ["经冬复历春", "熬过了冬天，又度过一个春天。"],
    ["近乡情更怯", "快要回到家乡，内心反而胆怯不安。"],
    ["不敢问来人", "甚至不敢向路上遇见的同乡打听家里消息。"]
  ],
  "background": "诗人被贬岭南，逃归途中渡汉江，离家越近内心越忐忑，怕听到家中坏消息。",
  "appreciation": "捕捉极真实的人性心理：久别还乡，不是狂喜，而是胆怯。短短二十字，把复杂矛盾的情绪写得入木三分。"
},
{
  "id": 323,
  "type": "唐诗",
  "title": "回乡偶书·其二",
  "author": "贺知章",
  "source": "《全唐诗》",
  "category": "亲情记忆",
  "text": "离别家乡岁月多，\n近来人事半消磨。\n惟有门前镜湖水，\n春风不改旧时波。",
  "translations": [
    ["离别家乡岁月多", "离开家乡已经度过许多年月。"],
    ["近来人事半消磨", "家乡的人和事大半已经变迁消逝。"],
    ["惟有门前镜湖水", "只有门前那一片镜湖的流水。"],
    ["春风不改旧时波", "春风吹拂之下，水波还和从前一样。"]
  ],
  "background": "贺知章晚年归乡，继《回乡偶书》第一首之后所作，感叹人事变迁，景物依旧。",
  "appreciation": "以人事变迁和湖水不变形成对照。物是人非的感慨不激烈，淡淡流露，余味悠长。"
},
{
  "id": 324,
  "type": "唐诗",
  "title": "边词",
  "author": "张敬忠",
  "source": "《全唐诗》",
  "category": "四时风物",
  "text": "五原春色旧来迟，\n二月垂杨未挂丝。\n即今河畔冰开日，\n正是长安花落时。",
  "translations": [
    ["五原春色旧来迟", "五原这地方春天向来来得很晚。"],
    ["二月垂杨未挂丝", "到了二月，杨柳还没有抽出柔丝。"],
    ["即今河畔冰开日", "如今河边冰块刚刚消融解冻。"],
    ["正是长安花落时", "而此时长安城里的花儿已经凋落。"]
  ],
  "background": "边塞诗，驻守北方边塞，对比边塞与京城物候差异。",
  "appreciation": "把边地和长安的春天放在一起对照，没有写苦情，借物候差别写出边塞的荒寒，含蓄蕴藉。"
},
{
  "id": 325,
  "type": "唐诗",
  "title": "黄鹤楼",
  "author": "崔颢",
  "source": "《全唐诗》",
  "category": "羁旅乡愁",
  "text": "昔人已乘黄鹤去，此地空余黄鹤楼。\n黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋鹦鹉洲。\n日暮乡关何处是？烟波江上使人愁。",
  "translations": [
    [
      "全文译意",
      "传说仙人乘着黄鹤离去，此地只留下黄鹤楼。黄鹤一去不再回返，千百年间只有白云飘荡。晴天汉阳树木清晰分明，鹦鹉洲上芳草繁茂。暮色沉沉，故乡在哪里，江上浩渺烟波勾起无尽乡愁。"
    ]
  ],
  "background": "诗人登临黄鹤楼，由神话传说写到眼前江景，触发起日暮怀归的情绪。",
  "appreciation": "前半咏古迹，有苍茫历史感；后半转入实景与乡愁。神话、景物、情思浑然一体，被后人推为唐人七律压卷之作。"
},
{
  "id": 326,
  "type": "唐诗",
  "title": "羌村三首·其三",
  "author": "杜甫",
  "source": "《杜工部集》",
  "category": "亲情记忆",
  "text": "群鸡正乱叫，客至鸡斗争。\n驱鸡上树木，始闻叩柴荆。\n父老四五人，问我久远行。\n手中各有携，倾榼浊复清。",
  "translations": [
    [
      "全文译意",
      "院子里群鸡乱叫，有客人来鸡群争斗。把鸡驱赶到树上，才听见叩打柴门的声音。几位乡里父老，慰问我长久远行归来。每个人手里带着酒壶，倒出来的酒有浊也有清。"
    ]
  ],
  "background": "安史之乱，杜甫历尽艰险回到羌村家中，记录邻里父老登门慰问的生活场景。",
  "appreciation": "从鸡叫这样极细碎的日常写起，质朴写实。战乱年代普通人之间淳朴的情谊，朴素而动人。"
},
{
  "id": 327,
  "type": "唐诗",
  "title": "江南逢李龟年",
  "author": "杜甫",
  "source": "《杜工部集》",
  "category": "历史名著",
  "text": "岐王宅里寻常见，崔九堂前几度闻。\n正是江南好风景，落花时节又逢君。",
  "translations": [
    [
      "全文译意",
      "过去常在岐王府邸见到你，崔九堂前也多次听过你的演唱。如今江南风光正好，在落花飘零的时候，又和你相逢。"
    ]
  ],
  "background": "安史之乱之后，流落江南的杜甫偶遇旧宫廷乐师李龟年。昔日繁华和当下落魄形成巨大落差。",
  "appreciation": "全诗没有一句直接诉苦。只用今昔场景对照，“落花时节”四字，写尽时代变迁、个人沦落，含蓄厚重。"
},
{
  "id": 328,
  "type": "唐诗",
  "title": "逢雪宿芙蓉山主人",
  "author": "刘长卿",
  "source": "《全唐诗》",
  "category": "羁旅乡愁",
  "text": "日暮苍山远，\n天寒白屋贫。\n柴门闻犬吠，\n风雪夜归人。",
  "translations": [
    ["日暮苍山远", "天色已晚，青山路途还十分遥远。"],
    ["天寒白屋贫", "天气寒冷，简陋茅屋显得清贫萧瑟。"],
    ["柴门闻犬吠", "柴门外传来一阵狗叫声。"],
    ["风雪夜归人", "原来是有人冒着风雪夜里回到家中。"]
  ],
  "background": "诗人冬日旅途，傍晚投宿山中贫苦人家，记录风雪山中的所见所闻。",
  "appreciation": "四句像一幅连续的镜头：远景苍山，近景茅屋，听觉犬吠，结尾点出风雪归人。画面清冷，意境留白丰富。"
},
{
  "id": 329,
  "type": "唐诗",
  "title": "送灵澈上人",
  "author": "刘长卿",
  "source": "《全唐诗》",
  "category": "友情相逢",
  "text": "苍苍竹林寺，\n杳杳钟声晚。\n荷笠带斜阳，\n青山独归远。",
  "translations": [
    ["苍苍竹林寺", "青翠幽深的竹林掩映着寺院。"],
    ["杳杳钟声晚", "傍晚，悠远的钟声缓缓传来。"],
    ["荷笠带斜阳", "僧人背着斗笠，身上披着落日余晖。"],
    ["青山独归远", "独自向着青山深处，越走越远。"]
  ],
  "background": "送别灵澈和尚归去山林，全诗没有直接写离别伤感，重在描绘归僧的背影。",
  "appreciation": "以钟声、斜阳、青山勾勒出僧人远去的画面。淡墨素描，静穆悠远，离别之情藏在景物之中。"
},
{
  "id": 330,
  "type": "唐诗",
  "title": "听弹琴",
  "author": "刘长卿",
  "source": "《全唐诗》",
  "category": "月色清寂",
  "text": "泠泠七弦上，\n静听松风寒。\n古调虽自爱，\n今人多不弹。",
  "translations": [
    ["泠泠七弦上", "七弦琴上发出清越泠泠的琴声。"],
    ["静听松风寒", "静静听那《风入松》的凄清曲调。"],
    ["古调虽自爱", "我虽然十分喜爱古朴的曲调。"],
    ["今人多不弹", "如今的世人大多已经不再弹奏。"]
  ],
  "background": "听古琴有感，借古调无人欣赏，寄托自己不被当世理解的感慨。",
  "appreciation": "由琴声生发出对时代审美的感叹。短小精炼，表面咏琴，实则写怀才不遇，含蓄内敛。"
},
{
  "id": 331,
  "type": "宋词",
  "title": "卜算子·黄州定慧院寓居作",
  "author": "苏轼",
  "source": "《东坡乐府》",
  "category": "人生哲理",
  "text": "缺月挂疏桐，漏断人初静。\n谁见幽人独往来，缥缈孤鸿影。\n惊起却回头，有恨无人省。\n拣尽寒枝不肯栖，寂寞沙洲冷。",
  "translations": [
    [
      "全文译意",
      "残缺的月亮挂在稀疏梧桐树上，夜深漏壶声停，四周寂静。有谁看见幽居之人独自徘徊，如同缥缈孤雁的身影。受惊飞起又回头回望，心中的愁恨无人懂得。挑遍寒枝也不肯随意栖息，宁愿落身在寂寞清冷沙洲。"
    ]
  ],
  "background": "乌台诗案之后，苏轼被贬黄州，寓居定慧院。以孤鸿自喻，写自己孤高、不肯随世俗的心境。",
  "appreciation": "孤鸿即是词人自我写照。不愿苟合世俗，宁可承受孤独冷寂。意象清冷，托物言志，寄托贬谪时期的人格坚守。"
},
{
  "id": 332,
  "type": "宋词",
  "title": "西江月·世事一场大梦",
  "author": "苏轼",
  "source": "《东坡乐府》",
  "category": "人生哲理",
  "text": "世事一场大梦，人生几度秋凉？\n夜来风叶已鸣廊，看取眉头鬓上。\n酒贱常愁客少，月明多被云妨。\n中秋谁与共孤光，把盏凄然北望。",
  "translations": [
    [
      "全文译意",
      "世间万事仿佛一场大梦，人生能经历几回清冷秋天。夜里风吹树叶在长廊作响，看看眉间鬓角，年华已经老去。酒价低廉，却常常发愁来客稀少；皎洁明月屡屡被乌云遮蔽。中秋之夜，谁能和我共享这月光，只能举杯凄然向北遥望。"
    ]
  ],
  "background": "苏轼黄州中秋所作。历经灾祸，感叹世事如梦，中秋孤独望月，内心满是失意。",
  "appreciation": "将人生比作梦境，明月被乌云遮蔽隐喻贤才受谗。悲凉之中，是苏轼对命运的沉思，情感沉郁。"
},
{
  "id": 333,
  "type": "宋词",
  "title": "忆秦娥·箫声咽",
  "author": "李白",
  "source": "《全唐诗》",
  "category": "历史名著",
  "text": "箫声咽，秦娥梦断秦楼月。\n秦楼月，年年柳色，灞陵伤别。\n乐游原上清秋节，咸阳古道音尘绝。\n音尘绝，西风残照，汉家陵阙。",
  "translations": [
    [
      "全文译意",
      "箫声凄咽，秦娥从梦里惊醒，只见秦楼之上一轮明月。秦楼的明月下，年年柳色青青，灞桥之上总上演离别。乐游原上清秋时节，通往咸阳古道，音信早已断绝。音信断绝，西风吹动，落日余晖照在汉代帝王陵墓。"
    ]
  ],
  "background": "传为李白所作，被称为词中鼻祖。上片写女子伤别，下片转入怀古，个人离愁上升到历史沧桑。",
  "appreciation": "以月、柳、灞陵写离别，末句“西风残照，汉家陵阙”境界雄浑苍凉，把儿女情思拓展到历史兴亡感慨。"
},
{
  "id": 334,
  "type": "宋词",
  "title": "相见欢·林花谢了春红",
  "author": "李煜",
  "source": "《南唐二主词》",
  "category": "离别思念",
  "text": "林花谢了春红，太匆匆。\n无奈朝来寒雨晚来风。\n胭脂泪，相留醉，几时重。\n自是人生长恨水长东。",
  "translations": [
    [
      "全文译意",
      "树林间春花凋零，春光消逝实在太过匆匆。无可奈何，早晨冷雨，傍晚寒风不停摧残花朵。花瓣如同美人带泪，留恋相聚醉饮，不知何时能够再度相逢。人生本就有绵绵无尽的遗憾，就像江水永远向东奔流。"
    ]
  ],
  "background": "李煜亡国被俘之后的词作。借春花被风雨摧残，写故国逝去、人生长恨。",
  "appreciation": "惜花，也是惜自己命运。“人生长恨水长东”把个体悲痛化为普遍性的生命慨叹，沉痛而开阔。"
},
{
  "id": 335,
  "type": "元曲",
  "title": "凭栏人·寄征衣",
  "author": "姚燧",
  "source": "《全元散曲》",
  "category": "爱情情感",
  "text": "欲寄君衣君不还，\n不寄君衣君又寒。\n寄与不寄间，\n妾身千万难。",
  "translations": [
    ["欲寄君衣君不还", "想要给你寄过冬衣服，可你却不能归来。"],
    ["不寄君衣君又寒", "若是不寄，你又会受冻受寒。"],
    ["寄与不寄间", "到底是寄还是不寄。"],
    ["妾身千万难", "我的心中真是万般为难。"]
  ],
  "background": "元代小令，写思妇给远方征人准备冬衣的矛盾心理。",
  "appreciation": "抓住生活中两难抉择，没有华丽辞藻。短短四句，把女子牵挂又害怕对方不回家的复杂心理写得活灵活现。"
},
{
  "id": 336,
  "type": "元曲",
  "title": "天净沙·春",
  "author": "白朴",
  "source": "《天籁集》",
  "category": "四时风物",
  "text": "春山暖日和风，阑干楼阁帘栊，杨柳秋千院中。\n啼莺舞燕，小桥流水飞红。",
  "translations": [
    [
      "全文译意",
      "春日青山，暖阳和煦，微风轻拂。楼阁帘幕，庭院里杨柳与秋千相映。黄莺啼叫，燕子飞舞，小桥流水，花瓣随风飘落。"
    ]
  ],
  "background": "白朴四季天净沙组曲之春，铺写春日庭院风光。",
  "appreciation": "堆叠一组春日意象，动静结合。画面明媚柔和，勾勒出闲适明媚的春日庭院图景。"
},
{
  "id": 337,
  "type": "先秦诗歌",
  "title": "子衿",
  "author": "佚名",
  "source": "《诗经·郑风》",
  "category": "爱情情感",
  "text": "青青子衿，悠悠我心。\n纵我不往，子宁不嗣音？\n青青子佩，悠悠我思。\n纵我不往，子宁不来？\n挑兮达兮，在城阙兮。\n一日不见，如三月兮。",
  "translations": [
    [
      "全文译意",
      "你的青色衣领，牵动我绵长思念。就算我不能前去，你为何不捎来音信？你的青色佩玉，让我无尽牵挂。就算我不能前去，你怎么不主动前来？我在城楼上来回徘徊，一天不见你，仿佛隔了漫长的三个月。"
    ]
  ],
  "background": "《郑风》名篇，女子思念恋人，久候不至，在城门楼上徘徊等待。",
  "appreciation": "心理刻画细腻，反问句式把思念、埋怨、期盼交织。“一日不见，如三月兮”成为后世写相思的经典句子。"
},
{
  "id": 338,
  "type": "汉魏诗歌",
  "title": "行行重行行",
  "author": "佚名",
  "source": "《古诗十九首》",
  "category": "离别思念",
  "text": "行行重行行，与君生别离。\n相去万余里，各在天一涯。\n道路阻且长，会面安可知。\n胡马依北风，越鸟巢南枝。",
  "translations": [
    [
      "全文译意",
      "走啊走啊，就这样活生生与你别离。相隔万里，各在天的一边。道路艰险又漫长，再相见哪能预料。北方的马依恋北风，南方的鸟儿筑巢也偏向向南的树枝。"
    ]
  ],
  "background": "《古诗十九首》第一首，写女子思念远行不归的爱人。",
  "appreciation": "语言朴素自然。胡马、越鸟以动物不忘故土，反衬人漂泊不归，含蓄深沉，是汉代文人五言诗典范。"
},
{
  "id": 339,
  "type": "汉魏诗歌",
  "title": "迢迢牵牛星",
  "author": "佚名",
  "source": "《古诗十九首》",
  "category": "爱情情感",
  "text": "迢迢牵牛星，皎皎河汉女。\n纤纤擢素手，札札弄机杼。\n终日不成章，泣涕零如雨。\n河汉清且浅，相去复几许。\n盈盈一水间，脉脉不得语。",
  "translations": [
    [
      "全文译意",
      "遥远的牵牛星，明亮的织女星。织女伸出纤细洁白的手，织布机札札作响。一整天织不成完整花纹，眼泪如雨落下。银河又清又浅，彼此距离又能有多远。就隔着这盈盈一水，只能含情凝望，不能交谈。"
    ]
  ],
  "background": "借牛郎织女银河相隔的神话，写人间相爱却不得相聚的痛苦。",
  "appreciation": "叠词大量使用，音韵优美。“盈盈一水间，脉脉不得语”，咫尺天涯，无言相望，把相爱分离的痛苦写得哀婉动人。"
},
{
  "id": 340,
  "type": "古文",
  "title": "爱莲说",
  "author": "周敦颐",
  "source": "《周元公集》",
  "category": "人生哲理",
  "text": "水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。\n予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。",
  "translations": [
    [
      "全文译意",
      "水上陆地草木花卉，可爱的很多。晋代陶渊明只喜爱菊花；唐代以来世人十分喜爱牡丹。我唯独喜爱莲花，它从淤泥长出却不被沾染，经过清水洗涤却不妖艳。茎内中空外形挺直，不生藤蔓旁枝，香气越远越清，洁净挺立，只可以远远观赏，不可以轻慢把玩。"
    ]
  ],
  "background": "周敦颐北宋理学家。以菊、牡丹、莲三种花对比，托物言志，赞美君子品格。",
  "appreciation": "以花喻人。菊花代表隐逸，牡丹代表富贵，莲花象征洁身自好的君子。对比鲜明，成为千古咏物名篇。"
},
{
  "id": 341,
  "type": "古文",
  "title": "陋室铭",
  "author": "刘禹锡",
  "source": "《刘禹锡集》",
  "category": "人生哲理",
  "text": "山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。\n苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。",
  "translations": [
    [
      "全文译意",
      "山不在于高，有仙人就会闻名；水不在于深，有蛟龙就显灵。这简陋居室，只因我的品德而芬芳。青苔漫上台阶，草色映入帘幕。往来谈笑都是博学大儒，没有浅薄俗人。可以弹奏朴素古琴，阅读佛经。没有喧闹音乐扰乱耳朵，没有官府公文劳累身体。"
    ]
  ],
  "background": "刘禹锡被贬时期所作。借描写简陋居室，表达安贫乐道，看重德行而轻视物质条件。",
  "appreciation": "短小铭文，骈散结合。不追求居室豪华，把品德修养作为核心，乐观旷达，朗朗上口。"
},
{
  "id": 342,
  "type": "先秦经典",
  "title": "劝学（节选）",
  "author": "荀子",
  "source": "《荀子·劝学》",
  "category": "学习求知",
  "text": "君子曰：学不可以已。\n青，取之于蓝，而青于蓝；冰，水为之，而寒于水。\n木直中绳，輮以为轮，其曲中规。虽有槁暴，不复挺者，輮使之然也。",
  "translations": [
    [
      "全文译意",
      "君子说，学习不可以停止。靛青取自蓝草，却比蓝草更青；冰由水凝结而成，却比水更寒冷。木材笔直合乎墨线，用火烘烤弯成车轮，弧度合乎圆规，就算晒干，也不再挺直，是加工使它变成这样。"
    ]
  ],
  "background": "《劝学》是荀子代表作，大量比喻论述后天学习、改造对人的重要意义。",
  "appreciation": "一连串生动比喻，论证后天学习塑造人。逻辑清晰，说理形象，是古代论说文的典范。"
},
{
  "id": 343,
  "type": "楚辞",
  "title": "橘颂（节选）",
  "author": "屈原",
  "source": "《楚辞·九章》",
  "category": "人生哲理",
  "text": "后皇嘉树，橘徕服兮。\n受命不迁，生南国兮。\n深固难徙，更壹志兮。\n绿叶素荣，纷其可喜兮。",
  "translations": [
    [
      "全文译意",
      "天地孕育的美好橘树，生来适应南方水土。禀受天命不可迁徙，生长在南国。根深蒂固难以迁移，意志专一坚定。碧绿树叶，洁白花朵，繁茂令人欣喜。"
    ]
  ],
  "background": "屈原早期作品，咏物赋，借橘树扎根南国不可移栽，比喻自己坚守故土、品格坚贞。",
  "appreciation": "中国文学史上较早完整咏物篇章。句句写橘，句句写人，借植物寄托坚守节操的志向。"
},
{
  "id": 344,
  "type": "唐诗",
  "title": "行宫",
  "author": "元稹",
  "source": "《全唐诗》",
  "category": "历史名著",
  "text": "寥落古行宫，\n宫花寂寞红。\n白头宫女在，\n闲坐说玄宗。",
  "translations": [
    ["寥落古行宫", "冷落萧条的古老行宫。"],
    ["宫花寂寞红", "宫中花朵寂寞地开得红艳。"],
    ["白头宫女在", "头发已经雪白的宫女还在这里。"],
    ["闲坐说玄宗", "闲坐着，谈论当年玄宗时代旧事。"]
  ],
  "background": "昔日繁华的行宫已经衰败，白头宫女追忆开元天宝旧事。",
  "appreciation": "二十个字，包含盛衰变迁。红花热闹反衬环境人物寂寞，“闲坐说玄宗”平淡一句话，有无尽沧桑。"
},
{
  "id": 345,
  "type": "唐诗",
  "title": "离思·其四",
  "author": "元稹",
  "source": "《元氏长庆集》",
  "category": "爱情情感",
  "text": "曾经沧海难为水，\n除却巫山不是云。\n取次花丛懒回顾，\n半缘修道半缘君。",
  "translations": [
    ["曾经沧海难为水", "见识过沧海浩瀚，别处的水再也难以吸引我。"],
    ["除却巫山不是云", "见过巫山的彩云，别处的云都算不上云彩。"],
    ["取次花丛懒回顾", "即使从繁花丛中走过，也懒得回头一望。"],
    ["半缘修道半缘君", "一半是因为修身，一半是因为怀念你。"]
  ],
  "background": "元稹悼念亡妻韦丛的悼亡诗。以沧海、巫山的比喻写对亡妻的刻骨铭心。",
  "appreciation": "前两句比喻盛大、一往情深。见过至美之后，其他都不值一提。成为悼念忠贞爱情的千古名句。"
}
{
  "id": 346,
  "type": "唐诗",
  "title": "遣悲怀·其二",
  "author": "元稹",
  "source": "《元氏长庆集》",
  "category": "亲情记忆",
  "text": "昔日戏言身后意，\n今朝都到眼前来。\n衣裳已施行看尽，\n针线犹存未忍开。",
  "translations": [
    ["昔日戏言身后意", "往日戏说死后之事的话语。"],
    ["今朝都到眼前来", "如今一件件都变成眼前现实。"],
    ["衣裳已施行看尽", "妻子的衣裳差不多已经施舍完毕。"],
    ["针线犹存未忍开", "她做过的针线遗物还在，我不忍心打开翻看。"]
  ],
  "background": "元稹《遣悲怀》为悼念亡妻韦丛所作。夫妻生前曾经玩笑谈及身后之事，妻子离世，旧物犹在，睹物思人，满是伤痛。",
  "appreciation": "全诗没有激烈的痛哭，全部从生活旧物落笔。衣裳、针线都是寻常物件，却承载生死离别之痛，平实语句，悲感入骨。"
},
{
  "id": 347,
  "type": "唐诗",
  "title": "马诗·其五",
  "author": "李贺",
  "source": "《李贺诗集》",
  "category": "人生哲理",
  "text": "大漠沙如雪，\n燕山月似钩。\n何当金络脑，\n快走踏清秋。",
  "translations": [
    ["大漠沙如雪", "大漠平沙，在月光下洁白如雪。"],
    ["燕山月似钩", "燕山上空的弯月好似弯钩。"],
    ["何当金络脑", "什么时候骏马能够戴上华贵的金络头。"],
    ["快走踏清秋", "在清爽的秋日旷野上自由驰骋。"]
  ],
  "background": "李贺《马诗》组诗，借咏马抒怀。骏马身怀才质却得不到重用，诗人以马自比，抒发怀才不遇的愤懑与理想。",
  "appreciation": "前两句勾勒辽阔清冷边塞夜景。后两句借骏马渴望驰骋，寄托渴望被赏识、建功立业的心愿。通篇托物言志，意境雄奇。"
},
{
  "id": 348,
  "type": "唐诗",
  "title": "南园·其六",
  "author": "李贺",
  "source": "《李贺诗集》",
  "category": "家国情怀",
  "text": "寻章摘句老雕虫，\n晓月当帘挂玉弓。\n不见年年辽海上，\n文章何处哭秋风。",
  "translations": [
    ["寻章摘句老雕虫", "长年累月雕琢辞章，不过是雕虫小技。"],
    ["晓月当帘挂玉弓", "晓月如弯弓，映照书斋帘幕。"],
    ["不见年年辽海上", "难道看不见辽海边疆年年战事不休。"],
    ["文章何处哭秋风", "写再多悲秋诗文，又有什么用处。"]
  ],
  "background": "李贺家居南园，有感书生无用。面对边疆战乱，反思埋头苦读雕琢文字，却不能为国效力的现实。",
  "appreciation": "诗人对书斋文人生活进行自我反省。不愿只做寻章摘句的文士，渴望投笔从戎，格局慷慨沉郁。"
},
{
  "id": 349,
  "type": "宋词",
  "title": "鹧鸪天·漠漠轻寒上小楼",
  "author": "秦观",
  "source": "《淮海居士长短句》",
  "category": "月色清寂",
  "text": "漠漠轻寒上小楼，晓阴无赖似穷秋。\n淡烟流水画屏幽。\n自在飞花轻似梦，无边丝雨细如愁。\n宝帘闲挂小银钩。",
  "translations": [
    [
      "全文译意",
      "薄薄寒意漫上小楼，清晨的阴云沉闷得如同深秋。画屏上淡烟流水，意境清幽。漫天飞花落如同梦境，绵绵细雨好似无尽闲愁。华贵的帘子随意挂在小小的银钩之上。"
    ]
  ],
  "background": "秦观被贬之后所作。全篇写闺中人春日闲愁，不写激烈悲苦，而是捕捉朦胧细微的情绪。",
  "appreciation": "以梦喻飞花，以愁喻细雨，比喻新颖奇特。通篇景物清冷幽淡，把无形的闲愁化为看得见的景物，含蓄婉转。"
},
{
  "id": 350,
  "type": "宋词",
  "title": "踏莎行·郴州旅舍",
  "author": "秦观",
  "source": "《淮海居士长短句》",
  "category": "羁旅乡愁",
  "text": "雾失楼台，月迷津渡。桃源望断无寻处。\n可堪孤馆闭春寒，杜鹃声里斜阳暮。\n驿寄梅花，鱼传尺素。砌成此恨无重数。\n郴江幸自绕郴山，为谁流下潇湘去。",
  "translations": [
    [
      "全文译意",
      "楼台消失在浓雾，渡口被月色迷蒙。望遍远方，找不到桃花源那样的乐土。怎能忍受孤寂馆舍紧闭，承受料峭春寒，夕阳暮色之中杜鹃声声啼叫。托驿使寄送梅花，托鱼雁传递书信，堆积起数不清的幽恨。郴江本来环绕郴山，究竟为谁，要滚滚流向潇湘。"
    ]
  ],
  "background": "秦观被贬郴州，困居旅舍。仕途失意，远离亲友，一腔幽怨借春夜景物倾泻而出。",
  "appreciation": "开头迷离凄冷，结尾借江水发问，无理而有情。将贬谪的苦闷、思念亲友的惆怅全部寄托山水，凄婉动人。"
},
{
  "id": 351,
  "type": "古文",
  "title": "病梅馆记",
  "author": "龚自珍",
  "source": "《龚自珍全集》（节选）",
  "category": "人生哲理",
  "text": "江宁之龙蟠，苏州之邓尉，杭州之西溪，皆产梅。\n或曰：梅以曲为美，直则无姿；以欹为美，正则无景；以疏为美，密则无态。",
  "translations": [
    [
      "全文译意",
      "南京龙蟠、苏州邓尉、杭州西溪，都出产梅花。有人说：梅枝干弯曲才算美，笔直就没有风姿；倾斜才算美，端正就没有景致；稀疏才算美，茂密就没有姿态。"
    ]
  ],
  "background": "晚清龚自珍借梅议政。写文人把梅花刻意扭曲修剪以求观赏，比喻社会束缚压抑人才，渴望解放天性。",
  "appreciation": "通篇托物议政。写病梅，实则写被压抑的人才。文章短小犀利，批判扭曲天性的世俗审美与社会风气。"
},
{
  "id": 352,
  "type": "清诗",
  "title": "己亥杂诗·其一二五",
  "author": "龚自珍",
  "source": "《龚自珍全集》",
  "category": "家国情怀",
  "text": "浩荡离愁白日斜，\n吟鞭东指即天涯。\n落红不是无情物，\n化作春泥更护花。",
  "translations": [
    ["浩荡离愁白日斜", "离愁浩浩荡荡，夕阳向西倾斜。"],
    ["吟鞭东指即天涯", "挥起马鞭向东，从此便是远隔天涯。"],
    ["落红不是无情物", "凋落的花朵并不是没有感情。"],
    ["化作春泥更护花", "变成春天泥土，依旧养护新生繁花。"]
  ],
  "background": "龚自珍辞官离开京城。满怀离京的愁闷，但依旧心系家国，愿意奉献自身。",
  "appreciation": "前两句写离京的惆怅。后两句以落花自喻，即使离开官场，依旧不忘家国，牺牲自我滋养后辈，境界高远。"
},
{
  "id": 353,
  "type": "清诗",
  "title": "己亥杂诗·其二百二十",
  "author": "龚自珍",
  "source": "《龚自珍全集》",
  "category": "家国情怀",
  "text": "九州生气恃风雷，\n万马齐喑究可哀。\n我劝天公重抖擞，\n不拘一格降人材。",
  "translations": [
    ["九州生气恃风雷", "神州大地蓬勃生机，要依靠风雷激荡。"],
    ["万马齐喑究可哀", "万马全部沉寂无声，终究是可悲局面。"],
    ["我劝天公重抖擞", "我奉劝上天重新振作精神。"],
    ["不拘一格降人材", "打破旧规格，降下各种各样优秀人才。"]
  ],
  "background": "晚清社会沉闷压抑，人才被埋没。诗人呼唤社会变革，希望打破桎梏，涌现大批济世人才。",
  "appreciation": "以风雷比喻变革，万马齐喑比喻社会死气沉沉。气势激昂，寄托对时代革新的热切期盼。"
},
{
  "id": 354,
  "type": "元曲",
  "title": "水仙子·夜雨",
  "author": "徐再思",
  "source": "《全元散曲》",
  "category": "羁旅乡愁",
  "text": "一声梧叶一声秋，一点芭蕉一点愁，三更归梦三更后。\n落灯花棋未收，叹新丰孤馆人留。\n枕上十年事，江南二老忧，都到心头。",
  "translations": [
    [
      "全文译意",
      "梧桐叶每落一声就添一分秋意，芭蕉雨每滴一点就增一分愁。三更之后才从归乡梦里醒来。灯花落下，残棋还未收拾，感叹自己困在异乡馆舍。十年来种种往事，江南家中双亲的担忧，全部涌上心头。"
    ]
  ],
  "background": "徐再思羁旅在外，秋夜听雨。夜雨触发归梦，回忆半生漂泊，挂念家中父母。",
  "appreciation": "开头叠字叠句，把秋雨和愁绪绑定在一起。从景物到梦境，再转到对父母牵挂，层层递进，写尽游子心酸。"
},
{
  "id": 355,
  "type": "宋词",
  "title": "唐多令·芦叶满汀洲",
  "author": "刘过",
  "source": "《龙洲词》",
  "category": "历史名著",
  "text": "芦叶满汀洲，寒沙带浅流。\n二十年重过南楼。\n柳下系船犹未稳，能几日，又中秋。\n黄鹤断矶头，故人今在否？\n旧江山浑是新愁。\n欲买桂花同载酒，终不似，少年游。",
  "translations": [
    [
      "全文译意",
      "沙洲铺满芦叶，寒冷沙滩旁浅浅流水。二十年后重新登上南楼。柳树下船只还没有系稳，过不了几天又到中秋。黄鹤矶头已经残破，旧日友人如今还在吗？旧日河山，到处都是新的忧愁。想要买来桂花，载酒同游，终究再也比不上少年时代的游历。"
    ]
  ],
  "background": "刘过重游安远楼（南楼），二十年光阴流转，国事飘摇，故人零落，对比少年往事，生出无限沧桑。",
  "appreciation": "今昔对比是全篇核心。同样的登临、同样的中秋，但是人事、家国都已经改变。结尾“终不似，少年游”，一语道尽岁月沧桑。"
},
{
  "id": 356,
  "type": "唐诗",
  "title": "金谷园",
  "author": "杜牧",
  "source": "《樊川文集》",
  "category": "历史名著",
  "text": "繁华事散逐香尘，\n流水无情草自春。\n日暮东风怨啼鸟，\n落花犹似坠楼人。",
  "translations": [
    ["繁华事散逐香尘", "金谷园昔日繁华，已经随着香尘消散。"],
    ["流水无情草自春", "流水漠然流淌，草木兀自迎来春天。"],
    ["日暮东风怨啼鸟", "黄昏东风之中，鸟儿啼叫满含哀怨。"],
    ["落花犹似坠楼人", "飘零的落花，仿佛当年坠楼的绿珠。"]
  ],
  "background": "凭吊金谷园古迹。西晋石崇豪奢，宠妾绿珠坠楼而死。时过境迁，只剩流水花草、落花飞鸟。",
  "appreciation": "把落花比作坠楼美人。不直接议论兴亡，借景物凭吊历史悲剧，含蓄哀婉，咏史而情景交融。"
},
{
  "id": 357,
  "type": "唐诗",
  "title": "清明夜",
  "author": "白居易",
  "source": "《白氏长庆集》",
  "category": "月色清寂",
  "text": "好风胧月清明夜，\n碧砌红轩刺史家。\n独绕回廊行复歇，\n遥听弦管暗看花。",
  "translations": [
    ["好风胧月清明夜", "清明夜晚，微风轻柔，月色朦胧。"],
    ["碧砌红轩刺史家", "青阶红廊，是刺史的府邸。"],
    ["独绕回廊行复歇", "独自绕回廊行走，走走停停。"],
    ["遥听弦管暗看花", "远远听音乐，默默观赏夜色下花朵。"]
  ],
  "background": "白居易担任地方刺史，清明之夜不外出游春，独自在家回廊漫步，在月色之中安静消遣。",
  "appreciation": "没有清明常见的悲戚，写独处夜色。行动舒缓，视听结合，表现文人安静内敛的闲淡心境。"
},
{
  "id": 358,
  "type": "宋词",
  "title": "浣溪沙·一向年光有限身",
  "author": "晏殊",
  "source": "《珠玉词》",
  "category": "人生哲理",
  "text": "一向年光有限身，等闲离别易销魂。\n酒筵歌席莫辞频。\n满目山河空念远，落花风雨更伤春。\n不如怜取眼前人。",
  "translations": [
    [
      "全文译意",
      "人生的时光本就有限，平常的离别也容易令人黯然神伤。酒宴歌会，不妨多多参与。望着辽阔山河，空想远方之人；风雨落花，更令人感伤春天逝去。不如好好珍惜眼前相伴的人。"
    ]
  ],
  "background": "晏殊词作，感叹生命短暂，离别频繁。不要总是怀念远方、追忆过往，应当珍惜当下拥有。",
  "appreciation": "上片感慨时光与离别。下片先写登高怀远、伤春，随即一转落到现实。理智与情感交织，通透而又温柔。"
},
{
  "id": 359,
  "type": "汉魏诗歌",
  "title": "七哀诗·其一",
  "author": "王粲",
  "source": "《王粲集》（节选）",
  "category": "家国情怀",
  "text": "西京乱无象，豺虎方遘患。\n复弃中国去，委身适荆蛮。\n亲戚对我悲，朋友相追攀。\n出门无所见，白骨蔽平原。",
  "translations": [
    [
      "全文译意",
      "长安战乱混乱不堪，凶恶之人制造祸乱。我离开中原，远赴荆楚避难。亲戚对着我悲伤，朋友依依不舍前来送别。出门放眼望去，平原之上白骨累累。"
    ]
  ],
  "background": "汉末董卓作乱，长安残破。王粲逃离长安去往荆州，亲眼目睹战乱带来的巨大灾难。",
  "appreciation": "建安文学代表作。记录乱世逃亡所见，白骨蔽平原一句直击战乱惨状，感情沉痛，真实再现时代苦难。"
},
{
  "id": 360,
  "type": "古文",
  "title": "捕蛇者说（节选）",
  "author": "柳宗元",
  "source": "《柳河东集》",
  "category": "民生百态",
  "text": "永州之野产异蛇：黑质而白章，触草木尽死；以啮人，无御之者。\n然得而腊之以为饵，可以已大风、挛踠、瘘、疠，去死肌，杀三虫。",
  "translations": [
    [
      "全文译意",
      "永州野外出产一种奇异毒蛇，黑色底色，白色花纹。碰到草木草木就枯死；咬到人，没有药物可以救治。但是捕捉之后晒干做药饵，可以治疗麻风、手脚痉挛、恶疮，去除坏死肌肉，驱除体内寄生虫。"
    ]
  ],
  "background": "柳宗元贬谪永州。通过捕蛇人的故事，揭露赋税比毒蛇还要害人，同情底层百姓的悲惨遭遇。",
  "appreciation": "以毒蛇开篇，层层铺垫。用对比手法，写出苛政对百姓的压迫，是古代讽喻散文的名篇。"
}

const STORAGE={favorites:"littlePoetryFavorites",history:"littlePoetryHistory",lastDaily:"littlePoetryLastDaily",paper:"littlePoetryPaper",font:"littlePoetryFont",vertical:"littlePoetryVertical"};
const $=id=>document.getElementById(id);
function getStorage(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{showToast("浏览器存储不可用")}}
let favorites=getStorage(STORAGE.favorites,[]).map(Number);
let history=getStorage(STORAGE.history,[]).map(Number);
let currentPoem=null,activeCategory="全部",activePage="home";
// 首次打开时立即标记当前页面，确保阅览室背景在手机和电脑上都能加载。
document.body.dataset.page = activePage;
const categories=["全部","山水自然","人生哲理","离别思念","爱情情感","家国情怀","历史名著","四时风物","月色清寂","羁旅乡愁","友情相逢","亲情记忆"];
const today=new Date();
$("todayDate").textContent=`${today.getFullYear()}.${String(today.getMonth()+1).padStart(2,"0")}.${String(today.getDate()).padStart(2,"0")}`;
const countEl=$("collectionCount");if(countEl)countEl.textContent=`馆藏作品 · ${poems.length} 篇`;
function getPoem(id){return poems.find(p=>p.id===Number(id))}
function showToast(message){const el=$("toast");el.textContent=message;el.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove("show"),1800)}
function addHistory(id){history=[Number(id),...history.filter(x=>Number(x)!==Number(id))].slice(0,50);saveStorage(STORAGE.history,history);window.dispatchEvent(new CustomEvent("poetry:history",{detail:{id:Number(id)}}))}
function escapeHTML(value){return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function poemCard(poem){return `<article class="poem-item" data-id="${poem.id}" tabindex="0" role="button"><h3>${escapeHTML(poem.title)}</h3><p>${escapeHTML(poem.text.replace(/\n/g," "))}</p><small>${escapeHTML(poem.author)} · ${escapeHTML(poem.category)}</small></article>`}
function bindPoemCards(root){root.querySelectorAll(".poem-item").forEach(item=>{const open=()=>selectPoem(item.dataset.id,true);item.addEventListener("click",open);item.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();open()}})})}
function dailyPoem(){const day=Math.floor(new Date(today.getFullYear(),today.getMonth(),today.getDate()).getTime()/86400000);return poems[day%poems.length]}
function renderDaily(){const p=dailyPoem();$("dailyContent").innerHTML=`<h2>${escapeHTML(p.text)}</h2><p class="author">—— ${escapeHTML(p.author)} · ${escapeHTML(p.title)}</p><p class="daily-intro">${escapeHTML(p.appreciation.slice(0,68))}……</p>`;$ ("dailyDetailBtn").onclick=()=>selectPoem(p.id,true)}
function selectPoem(id,scroll=false){currentPoem=getPoem(id);if(!currentPoem)return;addHistory(currentPoem.id);renderReadingCard();renderDetail();updateFavoriteButton();if(activePage!=="home"){activePage="home";updateNavigation();renderPageList()}if(scroll){$("reading").scrollIntoView({behavior:"smooth",block:"center"})}}
function randomPoem(){let list=poems.filter(p=>activeCategory==="全部"||p.category===activeCategory);if(!list.length)list=poems;let pool=list.filter(p=>!currentPoem||p.id!==currentPoem.id);const p=(pool.length?pool:list)[Math.floor(Math.random()*(pool.length||list.length))];selectPoem(p.id,false)}
function renderReadingCard(){const p=currentPoem;$("readingCard").innerHTML=`<div class="poem-content"><span class="poem-type">${escapeHTML(p.type)} · ${escapeHTML(p.category)}</span><h2>${escapeHTML(p.text)}</h2><p class="author">—— ${escapeHTML(p.author)}《${escapeHTML(p.title)}》</p><p class="poem-category">${escapeHTML(p.source)}</p></div>`;["favoriteBtn","copyBtn","cardBtn"].forEach(id=>$(id).disabled=false)}
function updateFavoriteButton(){if(!currentPoem)return;const yes=favorites.includes(currentPoem.id);$("favoriteBtn").textContent=yes?"♥ 已收藏":"♡ 收藏"}
function toggleFavorite(){if(!currentPoem)return;const id=currentPoem.id;if(favorites.includes(id)){favorites=favorites.filter(x=>x!==id);showToast("已从收藏中移除")}else{favorites.unshift(id);showToast("已收入收藏")}saveStorage(STORAGE.favorites,favorites);updateFavoriteButton();if(activePage==="favorites")renderPageList();window.dispatchEvent(new CustomEvent("poetry:favorite",{detail:{id:Number(id),isFavorite:favorites.includes(Number(id))}}))}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.opacity="0";document.body.appendChild(area);area.select();document.execCommand("copy");area.remove()}showToast("内容已复制")}catch{showToast("复制失败，请手动选择文字")}}
function copyPoem(){if(!currentPoem)return;copyText(`${currentPoem.text}\n\n—— ${currentPoem.author}《${currentPoem.title}》\n出处：${currentPoem.source}`)}
function renderDetail(){const p=currentPoem;const lines=p.translations.map(row=>`<div class="translation-line"><strong>${escapeHTML(row[0])}</strong><p>${escapeHTML(row[1])}</p></div>`).join("");$("detailContent").innerHTML=`<h2 class="detail-title">${escapeHTML(p.title)}</h2><p class="detail-author">${escapeHTML(p.author)} · ${escapeHTML(p.source)} · ${escapeHTML(p.type)}</p><div class="detail-block"><h3>一、作品原文</h3><p class="detail-original">${escapeHTML(p.text)}</p></div><div class="detail-block"><h3>二、逐句翻译</h3>${lines}</div><div class="detail-block"><h3>三、创作背景</h3><p>${escapeHTML(p.background)}</p></div><div class="detail-block"><h3>四、文学赏析</h3><p>${escapeHTML(p.appreciation)}</p></div><div class="detail-block"><h3>五、作品信息</h3><p>作者：${escapeHTML(p.author)}</p><p>出处：${escapeHTML(p.source)}</p><p>分类：${escapeHTML(p.category)}</p></div><div class="detail-actions"><button id="detailCopyBtn">复制这篇作品</button><button id="detailCardBtn">制作摘抄卡片</button></div>`;$("detailCopyBtn").onclick=copyPoem;$("detailCardBtn").onclick=createQuoteCard}
function renderCategories(){$("categoryList").innerHTML=categories.map(c=>`<button class="category-chip ${c===activeCategory?"active":""}" data-category="${escapeHTML(c)}">${escapeHTML(c)}</button>`).join("");$("categoryList").querySelectorAll("button").forEach(btn=>btn.addEventListener("click",()=>{activeCategory=btn.dataset.category;renderCategories();renderBrowse()}))}
function renderBrowse(){const list=poems.filter(p=>activeCategory==="全部"||p.category===activeCategory);$("browseGrid").innerHTML=list.map(poemCard).join("");bindPoemCards($("browseGrid"))}
function searchPoems(){const q=$("searchInput").value.trim().toLowerCase();const results=$("searchResults");if(!q){results.innerHTML="";$("searchHint").textContent="试着输入「苏轼」「明月」或一句你记得的诗。";return}const found=poems.filter(p=>[p.title,p.author,p.type,p.source,p.category,p.text,p.background,p.appreciation].join(" ").toLowerCase().includes(q));results.innerHTML=found.length?found.map(poemCard).join(""):`<div class="empty-list">没有找到相关作品。换个关键词试试。</div>`;$("searchHint").textContent=`找到 ${found.length} 篇相关作品`;bindPoemCards(results)}
function updateNavigation(){document.querySelectorAll(".nav-btn").forEach(btn=>btn.classList.toggle("active",btn.dataset.page===activePage))}
function renderPageList() {
    const home = activePage === "home";
    const profile = activePage === "profile";

    // 记录当前所在的页面，供动态背景识别
    document.body.dataset.page = activePage;

    $("homeView").hidden = !home;
    $("pageView").hidden = home || profile;
    $("profileView").hidden = !profile;

    if (home) return;

    if (profile) {
        if (window.poetryAccount) {
            window.poetryAccount.renderProfile();
        }
        return;
    }

    const isFav = activePage === "favorites";
    const ids = isFav ? favorites : history;

    $("pageTitle").textContent = isFav
        ? "我的收藏"
        : "阅读足迹";

    $("pageDescription").textContent = isFav
        ? `已收藏 ${ids.length} 篇作品。喜欢的文字会留在这里。`
        : `最近阅读的 ${ids.length} 篇作品，最多保留 50 条记录。`;

    $("pageGrid").innerHTML =
        ids.map(getPoem)
        .filter(Boolean)
        .map(poemCard)
        .join("")
        || `<div class="empty-list">
            这里暂时还没有作品。去阅览室拾取一篇喜欢的文字吧。
        </div>`;

    bindPoemCards($("pageGrid"));
}

document.querySelectorAll(".nav-btn").forEach(btn=>btn.addEventListener("click",()=>{activePage=btn.dataset.page;updateNavigation();renderPageList();window.scrollTo({top:0,behavior:"smooth"})}));
$("randomBtn").addEventListener("click",randomPoem);$("favoriteBtn").addEventListener("click",toggleFavorite);$("copyBtn").addEventListener("click",copyPoem);$("cardBtn").addEventListener("click",createQuoteCard);$("searchInput").addEventListener("input",searchPoems);$("clearSearch").addEventListener("click",()=>{$("searchInput").value="";searchPoems();$("searchInput").focus()});
// 纸张、字体和竖排偏好保存在本机。
function applyPreferences(){const paper=getStorage(STORAGE.paper,"snow"),font=getStorage(STORAGE.font,"song"),vertical=getStorage(STORAGE.vertical,false);document.body.dataset.paper=paper;document.body.dataset.font=font;document.body.classList.toggle("vertical-reading",!!vertical);$("paperSelect").value=paper;$("fontSelect").value=font;$("verticalBtn").setAttribute("aria-pressed",String(!!vertical));$("verticalBtn").textContent=vertical?"切换横排":"竖排阅读"}
$("paperSelect").addEventListener("change",e=>{document.body.dataset.paper=e.target.value;saveStorage(STORAGE.paper,e.target.value)});$("fontSelect").addEventListener("change",e=>{document.body.dataset.font=e.target.value;saveStorage(STORAGE.font,e.target.value)});$("verticalBtn").addEventListener("click",()=>{const on=!document.body.classList.contains("vertical-reading");document.body.classList.toggle("vertical-reading",on);saveStorage(STORAGE.vertical,on);$("verticalBtn").setAttribute("aria-pressed",String(on));$("verticalBtn").textContent=on?"切换横排":"竖排阅读"});
// 用 Web Audio API 本地合成轻柔环境音，不加载第三方音频文件。
let audioContext=null,masterGain=null,musicTimer=null,musicOn=false;function startMusic(){const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx){showToast("当前浏览器不支持背景音乐");return}audioContext=audioContext||new AudioCtx();if(audioContext.state==="suspended")audioContext.resume();masterGain=audioContext.createGain();masterGain.gain.value=.035;masterGain.connect(audioContext.destination);const notes=[220,261.63,329.63,392,329.63,293.66];let index=0;function playNote(){if(!musicOn||!audioContext)return;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type="sine";osc.frequency.value=notes[index%notes.length];gain.gain.setValueAtTime(0,audioContext.currentTime);gain.gain.linearRampToValueAtTime(.45,audioContext.currentTime+.8);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+3.5);osc.connect(gain);gain.connect(masterGain);osc.start();osc.stop(audioContext.currentTime+3.6);index++}playNote();musicTimer=setInterval(playNote,2600)}function stopMusic(){clearInterval(musicTimer);musicTimer=null;if(masterGain&&audioContext){masterGain.gain.setTargetAtTime(0,audioContext.currentTime,.15)}setTimeout(()=>{if(!musicOn&&masterGain){try{masterGain.disconnect()}catch{}masterGain=null}},700)}$("musicBtn").addEventListener("click",()=>{musicOn=!musicOn;$("musicBtn").setAttribute("aria-pressed",String(musicOn));$("musicBtn").innerHTML=musicOn?'<span class="music-dot"></span>暂停阅读音乐':'<span class="music-dot"></span>开启阅读音乐';if(musicOn)startMusic();else stopMusic()});
// 将当前作品绘制成可保存的 PNG 摘抄卡片。
function createQuoteCard(){if(!currentPoem)return;const p=currentPoem,canvas=document.createElement("canvas"),ctx=canvas.getContext("2d");canvas.width=1200;canvas.height=1500;ctx.fillStyle="#eef0f1";ctx.fillRect(0,0,1200,1500);ctx.strokeStyle="#cbd2d7";ctx.lineWidth=2;ctx.strokeRect(55,55,1090,1390);ctx.strokeStyle="#aab3b8";ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(120,190);ctx.lineTo(1080,190);ctx.stroke();ctx.fillStyle="#78858d";ctx.font="24px Georgia, serif";ctx.textAlign="left";ctx.fillText("LITTLE POETRY  ·  QUOTE CARD",120,145);ctx.fillStyle="#3c454b";ctx.font=`52px ${getComputedStyle(document.body).getPropertyValue("--font") || "serif"}`;ctx.textAlign="center";const lines=p.text.split("\n");const lineHeight=94;let y=560-(lines.length-1)*lineHeight/2;lines.forEach(line=>{ctx.fillText(line,600,y,900);y+=lineHeight});ctx.fillStyle="#737e85";ctx.font=`28px ${getComputedStyle(document.body).getPropertyValue("--font") || "serif"}`;ctx.fillText(`—— ${p.author}《${p.title}》`,600,1050);ctx.font=`21px ${getComputedStyle(document.body).getPropertyValue("--font") || "serif"}`;ctx.fillText(p.source,600,1110);ctx.fillStyle="#9aa3a8";ctx.font="20px Georgia, serif";ctx.fillText("以文字为笺，以岁月为墨。",600,1320);const link=document.createElement("a");link.download=`诗词拾光-${p.title}-摘抄卡.png`;link.href=canvas.toDataURL("image/png");link.click();showToast("摘抄卡片已生成")}
applyPreferences();renderDaily();renderCategories();renderBrowse();updateNavigation();

// 为账户模块提供兼容接口：保留原有 localStorage 键名与本地阅读体验。
window.poetryAppBridge={getFavorites:()=>[...favorites],getHistory:()=>[...history],setCloudLibrary:(fav,read)=>{favorites=[...new Set((fav||[]).map(Number))];history=[...new Set((read||[]).map(Number))].slice(0,50);saveStorage(STORAGE.favorites,favorites);saveStorage(STORAGE.history,history);updateFavoriteButton();if(activePage==="favorites"||activePage==="history")renderPageList()},getPoem:id=>getPoem(id),getPoems:()=>poems,refresh:()=>{if(activePage==="favorites"||activePage==="history")renderPageList()}};